insert into public.iskra_shared_kb (topic, topic_norm, body, tags) values
  ('Признаки равенства треугольников', public.iskra_kb_norm('Признаки равенства треугольников'), 'Первый признак: две стороны и угол между ними. Второй: сторона и два прилежащих к ней угла. Третий: три стороны. Угол обязательно должен лежать между сторонами, иначе признак не работает — это главная ошибка в задачах на доказательство. Записывают равенство так, чтобы соответствующие вершины стояли на одинаковых местах: треугольник ABC равен треугольнику MNK значит A против M, B против N, C против K. Отсюда сразу следует равенство всех остальных элементов — этим и пользуются дальше.', 'учёба, геометрия, треугольники, равенство'),
  ('Равнобедренный треугольник', public.iskra_kb_norm('Равнобедренный треугольник'), 'Равнобедренный — две стороны равны, их называют боковыми, третья основание. Углы при основании равны, а биссектриса, проведённая к основанию, одновременно медиана и высота. Обратно: если два угла треугольника равны, он равнобедренный. У равностороннего все стороны и все углы по 60 градусов, и он же равнобедренный. Сумма углов всегда 180 градусов, поэтому угол при вершине равен 180 минус два угла при основании. Эти два факта решают почти все задачи про равнобедренный треугольник.', 'учёба, геометрия, равнобедренный'),
  ('Неравенство треугольника', public.iskra_kb_norm('Неравенство треугольника'), 'Каждая сторона треугольника меньше суммы двух других. Проверяют по самой длинной стороне: если она меньше суммы двух коротких — треугольник существует. Стороны 3, 4 и 8 треугольник не образуют, потому что 8 больше 7. Отсюда рабочее правило: третья сторона больше разности и меньше суммы двух известных. В задачах это ограничение часто отсекает один из двух корней уравнения — забывают проверить, и в ответе остаётся невозможный треугольник. В прямоугольном треугольнике гипотенуза всегда больше любого катета.', 'учёба, геометрия, треугольник, стороны'),
  ('Сумма углов треугольника и внешний угол', public.iskra_kb_norm('Сумма углов треугольника и внешний угол'), 'Сумма углов любого треугольника равна 180 градусам, у четырёхугольника 360, у n-угольника 180 умножить на n минус 2. Внешний угол — смежный с внутренним, и он равен сумме двух внутренних, не смежных с ним. Поэтому внешний угол всегда больше каждого из них. В прямоугольном треугольнике острые углы в сумме дают 90. В равнобедренном, зная один угол, можно найти остальные, но надо помнить: тупым может быть только угол при вершине, углы при основании всегда острые.', 'учёба, геометрия, углы, треугольник'),
  ('Медиана, биссектриса, высота', public.iskra_kb_norm('Медиана, биссектриса, высота'), 'Медиана идёт из вершины и делит противоположную сторону пополам. Биссектриса делит угол пополам. Высота падает на противоположную сторону под прямым углом, у тупоугольного треугольника она может оказаться вне фигуры. Все три медианы пересекаются в одной точке, которая делит каждую медиану в отношении два к одному от вершины. Три биссектрисы тоже пересекаются в одной точке — это центр вписанной окружности, и он равноудалён от сторон. В равнобедренном треугольнике все три линии, проведённые к основанию, совпадают.', 'учёба, геометрия, медиана, биссектриса'),
  ('Параллельные прямые и секущая', public.iskra_kb_norm('Параллельные прямые и секущая'), 'Две прямые параллельны, если при пересечении секущей накрест лежащие углы равны, или соответственные равны, или сумма односторонних равна 180. Это три признака, и обратные к ним тоже верны: из параллельности следуют равенства углов. На практике: накрест лежащие — как буква Z, соответственные — как F, односторонние — как П. Углы с параллельными сторонами, вертикальные и смежные комбинируются в задачах, поэтому сначала расставь все известные углы, а потом ищи нужный. Сумма смежных углов 180, вертикальные равны.', 'учёба, геометрия, параллельные, углы'),
  ('Параллелограмм и его свойства', public.iskra_kb_norm('Параллелограмм и его свойства'), 'Параллелограмм — четырёхугольник, у которого противоположные стороны попарно параллельны. Противоположные стороны и углы равны, сумма углов, прилежащих к одной стороне, равна 180. Диагонали точкой пересечения делятся пополам. Признаки: если в четырёхугольнике две стороны равны и параллельны, это параллелограмм; если диагонали делятся пополам — тоже. Площадь равна стороне на высоту, проведённую к ней. Из параллелограмма получаются прямоугольник, ромб и квадрат, добавляя по одному свойству: прямой угол или равные стороны.', 'учёба, геометрия, параллелограмм'),
  ('Трапеция', public.iskra_kb_norm('Трапеция'), 'Трапеция — четырёхугольник с двумя параллельными сторонами, их называют основаниями, две другие — боковые. Средняя линия соединяет середины боковых сторон и равна половине суммы оснований. Площадь — полусумма оснований на высоту. Равнобедренная трапеция имеет равные боковые стороны и равные углы при каждом основании, её диагонали равны. Прямоугольная трапеция имеет два прямых угла. Сумма углов, прилежащих к боковой стороне, равна 180: это следует из параллельности оснований. Высота — перпендикуляр между основаниями.', 'учёба, геометрия, трапеция'),
  ('Прямоугольник, ромб, квадрат', public.iskra_kb_norm('Прямоугольник, ромб, квадрат'), 'Прямоугольник — параллелограмм с прямыми углами, у него диагонали равны. Ромб — параллелограмм с равными сторонами, у него диагонали перпендикулярны и делят углы пополам. Квадрат — и то, и другое сразу: прямые углы, равные стороны, равные и перпендикулярные диагонали. Площадь прямоугольника — произведение сторон, ромба — половина произведения диагоналей, квадрата — сторона в квадрате. Из всех прямоугольников с одинаковым периметром квадрат имеет наибольшую площадь, а из всех четырёхугольников с одинаковой площадью квадрат имеет наименьший периметр.', 'учёба, геометрия, прямоугольник, ромб'),
  ('Площадь треугольника и четырёхугольника', public.iskra_kb_norm('Площадь треугольника и четырёхугольника'), 'Площадь треугольника — половина основания на высоту, причём высота может быть вне фигуры. Через две стороны и угол между ними: половина произведения сторон на синус угла. Формула Герона считает площадь по трём сторонам через полупериметр. Площадь параллелограмма — основание на высоту, трапеции — полусумма оснований на высоту. Отношение площадей подобных фигур равно квадрату коэффициента подобия. Частая ошибка — брать в высоту боковую сторону: высота всегда перпендикулярна основанию, а не любая сторона.', 'учёба, геометрия, площадь'),
  ('Окружность: радиус, хорда, касательная', public.iskra_kb_norm('Окружность: радиус, хорда, касательная'), 'Окружность — все точки на одинаковом расстоянии от центра, круг — окружность вместе с внутренностью. Радиус — отрезок до точки окружности, диаметр — самый длинный, проходит через центр и равен двум радиусам. Хорда соединяет две точки окружности, диаметр — тоже хорда. Касательная касается окружности в одной точке и перпендикулярна радиусу, проведённому в эту точку. Две касательные из одной точки равны. Диаметр, перпендикулярный хорде, делит её пополам. Длина окружности 2πr, площадь круга πr².', 'учёба, геометрия, окружность, касательная'),
  ('Вписанный и центральный угол', public.iskra_kb_norm('Вписанный и центральный угол'), 'Центральный угол опирается на дугу вершиной в центре и равен дуге. Вписанный угол вершиной на окружности равен половине дуги, поэтому вписанный угол вдвое меньше центрального, опирающегося на ту же дугу. Отсюда: угол, опирающийся на диаметр, прямой, а вписанные углы на одну и ту же дугу равны. Четырёхугольник можно вписать в окружность, только если суммы противоположных углов равны 180. Угол между касательной и хордой тоже равен половине дуги, заключённой между ними. Это самые частые задачи на окружность в ОГЭ.', 'учёба, геометрия, вписанный угол'),
  ('Вписанная и описанная окружность', public.iskra_kb_norm('Вписанная и описанная окружность'), 'Вписанная окружность касается всех сторон, её центр — точка пересечения биссектрис, а радиус равен площади, делённой на полупериметр. Описанная проходит через все вершины, её центр — пересечение серединных перпендикуляров, радиус у треугольника равен отношению сторон к четырём площадям. Окружность можно вписать в четырёхугольник, только если суммы противоположных сторон равны. Радиус описанной окружности, делённый на два, — это не то же, что радиус вписанной: их путают в задачах постоянно. В прямоугольном треугольнике центр описанной окружности лежит на середине гипотенузы.', 'учёба, геометрия, окружность, вписанная'),
  ('Соотношения в прямоугольном треугольнике', public.iskra_kb_norm('Соотношения в прямоугольном треугольнике'), 'Теорема Пифагора: квадрат гипотенузы равен сумме квадратов катетов. Синус угла — противолежащий катет к гипотенузе, косинус — прилежащий к гипотенузе, тангенс — противолежащий к прилежащему. Высота, проведённая из прямого угла, делит гипотенузу на отрезки, и она равна корню из их произведения. Катет есть среднее пропорциональное между гипотенузой и своей проекцией. Катет, лежащий против угла 30 градусов, равен половине гипотенузы. В задачах сначала подписывай, где какой катет относительно нужного угла.', 'учёба, геометрия, прямоугольный треугольник'),
  ('Координаты на плоскости: расстояние и середина', public.iskra_kb_norm('Координаты на плоскости: расстояние и середина'), 'Точка задаётся парой чисел: первое по горизонтали, второе по вертикали, порядок менять нельзя. Расстояние между точками — корень из суммы квадратов разностей координат, это та же теорема Пифагора. Середина отрезка — среднее арифметическое координат: складываешь и делишь пополам. Уравнение прямой имеет вид y = kx + b, где k — наклон, b — сдвиг по вертикали. Параллельные прямые имеют одинаковый k, перпендикулярные — произведение наклонов минус единица. По координатам удобно проверять, прямоугольный ли треугольник: сравни квадраты сторон.', 'учёба, геометрия, координаты'),
  ('Симметрия и движение фигур', public.iskra_kb_norm('Симметрия и движение фигур'), 'Осевая симметрия — отражение относительно прямой: точка и её образ на равном расстоянии от оси, отрезок между ними перпендикулярен оси. Центральная симметрия — поворот на 180 градусов вокруг точки. При движении, то есть при симметрии, повороте и параллельном переносе, фигура переходит в равную: сохраняются длины, углы и площади, меняется только положение. Параллельный перенос сдвигает все точки на один и тот же вектор. В задачах на симметрию строй образы по точкам: сначала вершины, потом соединяй. Ось симметрии есть у равнобедренного треугольника, ромба, прямоугольника и окружности, у неё их бесконечно много.', 'учёба, геометрия, симметрия')
