-- Седьмая порция тем для общей базы Искры: школьные предметы, продолжение.
-- Часть 4: геометрия, 7–8 класс.
-- Запускать целиком в SQL Editor проекта: повторный запуск безопасен.
-- Ожидаемый результат в конце: одно число — сколько всего тем в базе.

on conflict (topic_norm) do update
  set body = excluded.body,
      tags = excluded.tags,
      active = true,
      updated_at = now();

select count(*) as тем_в_общей_базе from public.iskra_shared_kb where active;
